function(container, apiUrl, tables) {
  // テーブルインデックス: 信頼度スコアテーブル = 0
  const tableIndex = 0;
  const tbody = container.querySelector("#score-result-tbody");
  const noResults = container.querySelector("#no-results");
  const resultCount = container.querySelector("#result-count");
  const scoreSlider = container.querySelector("#score-slider");
  const scoreDisplay = container.querySelector("#score-display");

  // スコアスライダーの表示更新
  scoreSlider.addEventListener("input", () => {
    scoreDisplay.textContent = scoreSlider.value;
  });

  // 再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = "";
      noResults.style.display = "block";
      resultCount.textContent = "0";
      return;
    }
    noResults.style.display = "none";
    tbody.innerHTML = rows.map(r => {
      const totalScore = r.総合スコア || r.total_score || 0;
      const completenessScore = r.完全性スコア || r.completeness_score || 0;
      const accuracyScore = r.正確性スコア || r.accuracy_score || 0;
      const consistencyScore = r.一貫性スコア || r.consistency_score || 0;
      const channel = r.チャネル || r.channel || "—";
      const validationStatus = r.検証ステータス || r.validation_status || "—";
      const correctionHistory = r.修正履歴 || r.correction_history || "なし";
      const duplicateDetection = r.重複検出 || r.duplicate_detection || "なし";
      const channelConflict = r.チャネル間矛盾 || r.channel_conflict || "なし";
      const orderId = r.受注ID || r.order_id || r.id || "—";
      const customerName = r.顧客名 || r.customer_name || "—";

      // スコアに応じた色付け
      const scoreColor = totalScore >= 80 ? "#4ade80" : totalScore >= 50 ? "#fbbf24" : "#ef4444";
      const statusBgColor = validationStatus === "合格" ? "rgba(74,222,128,0.15)" : validationStatus === "不合格" ? "rgba(239,68,68,0.15)" : "rgba(251,191,36,0.15)";

      return `
        <tr data-id="${orderId}" style="border-bottom: 1px solid rgba(255,255,255,0.05); hover: background: rgba(255,255,255,0.02);">
          <td style="padding: 8px; color: var(--text);">${orderId}</td>
          <td style="padding: 8px; color: var(--text);">${customerName}</td>
          <td style="padding: 8px; text-align: center; color: ${scoreColor}; font-weight: 600;">${totalScore}</td>
          <td style="padding: 8px; text-align: center; color: var(--text);">${completenessScore}</td>
          <td style="padding: 8px; text-align: center; color: var(--text);">${accuracyScore}</td>
          <td style="padding: 8px; text-align: center; color: var(--text);">${consistencyScore}</td>
          <td style="padding: 8px; color: var(--text);">${channel}</td>
          <td style="padding: 8px;">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${statusBgColor}; color: var(--text); font-size: 11px;">${validationStatus}</span>
          </td>
          <td style="padding: 8px; text-align: center; color: var(--text);">${correctionHistory === "あり" ? "✓" : "—"}</td>
          <td style="padding: 8px; text-align: center; color: var(--text);">${duplicateDetection === "検出" ? "⚠" : "—"}</td>
          <td style="padding: 8px; text-align: center; color: var(--text);">${channelConflict === "検出" ? "⚠" : "—"}</td>
          <td style="padding: 8px; text-align: center;">
            <button class="action-btn secondary detail-btn" data-id="${orderId}" style="padding: 3px 8px; font-size: 10px;">詳細</button>
          </td>
        </tr>
      `;
    }).join("");
    resultCount.textContent = rows.length;
  }

  // 初期データ表示
  renderRows(tables[0]?.records || []);

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const minScore = parseInt(container.querySelector("#min-score").value) || 0;
    const maxScore = parseInt(container.querySelector("#max-score").value) || 100;
    const trustLevel = container.querySelector("#trust-level").value;
    const orderId = container.querySelector("#order-id-search").value.toLowerCase();
    const customerName = container.querySelector("#customer-name-search").value.toLowerCase();
    const channel = container.querySelector("#channel-filter").value;
    const validationStatus = container.querySelector("#validation-status-filter").value;
    const correctionHistory = container.querySelector("#correction-history-filter").value;
    const ocrConfidence = container.querySelector("#ocr-confidence-filter").value;
    const duplicateDetection = container.querySelector("#duplicate-detection-filter").value;
    const channelConflict = container.querySelector("#channel-conflict-filter").value;

    const allRows = await window.aivicApi.list(tableIndex) || tables[0]?.records || [];

    const filtered = allRows.filter(r => {
      const totalScore = r.総合スコア || r.total_score || 0;
      const rOrderId = (r.受注ID || r.order_id || r.id || "").toLowerCase();
      const rCustomerName = (r.顧客名 || r.customer_name || "").toLowerCase();
      const rChannel = r.チャネル || r.channel || "";
      const rValidationStatus = r.検証ステータス || r.validation_status || "";
      const rCorrectionHistory = r.修正履歴 || r.correction_history || "";
      const rOcrConfidence = r.AI_OCR信頼度 || r.ocr_confidence || 0;
      const rDuplicateDetection = r.重複検出 || r.duplicate_detection || "";
      const rChannelConflict = r.チャネル間矛盾 || r.channel_conflict || "";

      // スコア範囲チェック
      if (totalScore < minScore || totalScore > maxScore) return false;

      // 信頼度レベルチェック
      if (trustLevel === "high" && totalScore < 80) return false;
      if (trustLevel === "medium" && (totalScore < 50 || totalScore >= 80)) return false;
      if (trustLevel === "low" && totalScore >= 50) return false;

      // テキスト検索
      if (orderId && !rOrderId.includes(orderId)) return false;
      if (customerName && !rCustomerName.includes(customerName)) return false;

      // フィルタ条件
      if (channel && rChannel !== channel) return false;
      if (validationStatus && rValidationStatus !== validationStatus) return false;
      if (correctionHistory === "有" && rCorrectionHistory !== "あり") return false;
      if (correctionHistory === "無" && rCorrectionHistory === "あり") return false;
      if (ocrConfidence === "high" && rOcrConfidence < 80) return false;
      if (ocrConfidence === "medium" && (rOcrConfidence < 50 || rOcrConfidence >= 80)) return false;
      if (ocrConfidence === "low" && rOcrConfidence >= 50) return false;
      if (duplicateDetection === "detected" && rDuplicateDetection !== "検出") return false;
      if (duplicateDetection === "not-detected" && rDuplicateDetection === "検出") return false;
      if (channelConflict === "detected" && rChannelConflict !== "検出") return false;
      if (channelConflict === "not-detected" && rChannelConflict === "検出") return false;

      return true;
    });

    renderRows(filtered);
  });

  // リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#score-slider").value = 50;
    container.querySelector("#score-display").textContent = "50";
    container.querySelector("#min-score").value = 0;
    container.querySelector("#max-score").value = 100;
    container.querySelector("#trust-level").value = "";
    container.querySelector("#order-id-search").value = "";
    container.querySelector("#customer-name-search").value = "";
    container.querySelector("#channel-filter").value = "";
    container.querySelector("#validation-status-filter").value = "";
    container.querySelector("#correction-history-filter").value = "";
    container.querySelector("#ocr-confidence-filter").value = "";
    container.querySelector("#duplicate-detection-filter").value = "";
    container.querySelector("#channel-conflict-filter").value = "";
    renderRows(tables[0]?.records || []);
  });

  // CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(tableIndex) || tables[0]?.records || [];
    if (!rows.length) {
      alert("エクスポート対象データがありません");
      return;
    }
    const headers = ["受注ID", "顧客名", "総合スコア", "完全性", "正確性", "一貫性", "チャネル", "検証ステータス", "修正履歴", "重複検出", "チャネル間矛盾"];
    const csv = [
      "\uFEFF" + headers.join(","),
      ...rows.map(r => [
        r.受注ID || r.order_id || r.id || "",
        r.顧客名 || r.customer_name || "",
        r.総合スコア || r.total_score || 0,
        r.完全性スコア || r.completeness_score || 0,
        r.正確性スコア || r.accuracy_score || 0,
        r.一貫性スコア || r.consistency_score || 0,
        r.チャネル || r.channel || "",
        r.検証ステータス || r.validation_status || "",
        r.修正履歴 || r.correction_history || "",
        r.重複検出 || r.duplicate_detection || "",
        r.チャネル間矛盾 || r.channel_conflict || ""
      ].map(v => `"${String(v).replace(/"/g, '""')}"`).join(","))
    ].join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "score_filter_export.csv";
    link.click();
  });

  // 詳細ボタン（行クリック）
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const orderId = detailBtn.dataset.id;
      // 詳細確認・修正画面へ遷移
      window.showScreen("scr-1781413282852");
    }
  });
}

function(container, apiUrl, tables) {
  // ========== 1. 状態管理 ==========
  let currentOcrResult = null;
  let extractedFields = {};
  let correctionHistory = [];

  // ========== 2. 音声制御 ==========
  const volumeSlider = container.querySelector("#voice-volume");
  const volumeDisplay = container.querySelector("#volume-display");
  const btnPlayVoice = container.querySelector("#btn-play-voice");
  const btnPauseVoice = container.querySelector("#btn-pause-voice");

  volumeSlider.addEventListener("input", (e) => {
    volumeDisplay.textContent = e.target.value + "%";
  });

  btnPlayVoice.addEventListener("click", () => {
    const volume = volumeSlider.value;
    alert(`音声ガイダンス再生中（音量: ${volume}%）\n\n「受注書類をスキャナにセットしてください」`);
  });

  btnPauseVoice.addEventListener("click", () => {
    alert("音声ガイダンスを一時停止しました");
  });

  // ========== 3. カメラ/スキャナ操作 ==========
  const btnCamera = container.querySelector("#btn-camera");
  const btnScanner = container.querySelector("#btn-scanner");
  const imagePreview = container.querySelector("#image-preview");

  btnCamera.addEventListener("click", () => {
    // シミュレーション: ダミー画像を表示
    imagePreview.innerHTML = `
      <div style="text-align: center; color: var(--text);">
        <div style="font-size: 14px; margin-bottom: 8px;">📸 カメラから取得した画像</div>
        <div style="width: 200px; height: 150px; background: linear-gradient(135deg, rgba(255,255,255,0.1), rgba(255,255,255,0.05)); border-radius: 4px; margin: 0 auto; display: flex; align-items: center; justify-content: center; font-size: 12px; color: var(--text-muted);">
          [受注書類画像]
        </div>
      </div>
    `;
    alert("カメラが起動しました。受注書類を撮影してください。");
  });

  btnScanner.addEventListener("click", () => {
    imagePreview.innerHTML = `
      <div style="text-align: center; color: var(--text);">
        <div style="font-size: 14px; margin-bottom: 8px;">🖨️ スキャナから取得した画像</div>
        <div style="width: 200px; height: 150px; background: linear-gradient(135deg, rgba(255,255,255,0.1), rgba(255,255,255,0.05)); border-radius: 4px; margin: 0 auto; display: flex; align-items: center; justify-content: center; font-size: 12px; color: var(--text-muted);">
          [受注書類スキャン画像]
        </div>
      </div>
    `;
    alert("スキャナが起動しました。受注書類をスキャンしてください。");
  });

  // ========== 4. OCR処理 ==========
  const btnStartOcr = container.querySelector("#btn-start-ocr");
  const ocrProgressBar = container.querySelector("#ocr-progress-bar");
  const ocrStatus = container.querySelector("#ocr-status");
  const extractedDataDiv = container.querySelector("#extracted-data");
  const scoreOverall = container.querySelector("#score-overall");
  const lowConfidenceCount = container.querySelector("#low-confidence-count");

  btnStartOcr.addEventListener("click", async () => {
    if (!imagePreview.textContent.includes("画像")) {
      alert("先にカメラまたはスキャナで画像を取得してください");
      return;
    }

    ocrStatus.textContent = "処理中...";
    ocrProgressBar.style.width = "0%";
    btnStartOcr.disabled = true;

    // シミュレーション: 進捗バーアニメーション
    let progress = 0;
    const interval = setInterval(() => {
      progress += Math.random() * 30;
      if (progress > 100) progress = 100;
      ocrProgressBar.style.width = progress + "%";

      if (progress >= 100) {
        clearInterval(interval);
        ocrStatus.textContent = "完了";
        btnStartOcr.disabled = false;

        // ダミーOCR結果
        currentOcrResult = {
          customer_name: { value: "山田太郎", confidence: 95 },
          order_amount: { value: "¥150,000", confidence: 88 },
          order_date: { value: "2025-05-23", confidence: 92 },
          delivery_address: { value: "東京都渋谷区道玄坂1-2-3", confidence: 75 },
          phone: { value: "090-1234-5678", confidence: 85 },
          email: { value: "yamada@example.com", confidence: 70 }
        };

        extractedFields = { ...currentOcrResult };
        renderExtractedData();
        updateConfidenceScores();
      }
    }, 300);
  });

  function renderExtractedData() {
    const fieldLabels = {
      customer_name: "顧客名",
      order_amount: "受注金額",
      order_date: "受注日",
      delivery_address: "配送先住所",
      phone: "電話番号",
      email: "メールアドレス"
    };

    extractedDataDiv.innerHTML = Object.entries(currentOcrResult)
      .map(([key, data]) => {
        const isLowConfidence = data.confidence < 80;
        const bgColor = isLowConfidence ? "rgba(255, 106, 0, 0.1)" : "rgba(255,255,255,0.04)";
        const borderColor = isLowConfidence ? "rgba(255, 106, 0, 0.3)" : "rgba(255,255,255,0.12)";
        return `
          <div style="padding: 8px; margin-bottom: 6px; background: ${bgColor}; border: 1px solid ${borderColor}; border-radius: 4px;">
            <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 2px;">${fieldLabels[key]}</div>
            <div style="font-size: 12px; color: var(--text); margin-bottom: 4px; word-break: break-word;">${data.value}</div>
            <div style="font-size: 10px; color: ${isLowConfidence ? '#ff6a00' : 'var(--text-muted)'};">
              信頼度: ${data.confidence}% ${isLowConfidence ? '⚠️' : '✓'}
            </div>
          </div>
        `;
      })
      .join("");
  }

  function updateConfidenceScores() {
    const scores = Object.values(currentOcrResult).map(d => d.confidence);
    const overall = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);
    const lowCount = scores.filter(s => s < 80).length;

    scoreOverall.textContent = overall + "%";
    lowConfidenceCount.textContent = lowCount;
  }

  // ========== 5. 手動修正 ==========
  const correctionField = container.querySelector("#correction-field");
  const correctionValue = container.querySelector("#correction-value");
  const correctionReason = container.querySelector("#correction-reason");
  const btnApplyCorrection = container.querySelector("#btn-apply-correction");

  btnApplyCorrection.addEventListener("click", () => {
    if (!correctionField.value || !correctionValue.value || !correctionReason.value) {
      alert("修正項目、修正値、修正理由をすべて入力してください");
      return;
    }

    const fieldKey = correctionField.value;
    const oldValue = currentOcrResult[fieldKey]?.value || "";
    const newValue = correctionValue.value;

    // 修正履歴に記録
    correctionHistory.push({
      field: fieldKey,
      oldValue,
      newValue,
      reason: correctionReason.value,
      timestamp: new Date().toLocaleString("ja-JP")
    });

    // 抽出データを更新
    if (currentOcrResult[fieldKey]) {
      currentOcrResult[fieldKey].value = newValue;
      currentOcrResult[fieldKey].confidence = 100; // 手動修正は信頼度100%
    }

    renderExtractedData();
    updateConfidenceScores();

    // フォームをリセット
    correctionField.value = "";
    correctionValue.value = "";
    correctionReason.value = "";

    alert("修正を適用しました");
  });

  // ========== 6. 確定送信 ==========
  const btnConfirmSubmit = container.querySelector("#btn-confirm-submit");
  const btnCancel = container.querySelector("#btn-cancel");

  btnConfirmSubmit.addEventListener("click", async () => {
    if (!currentOcrResult) {
      alert("OCR処理を実行してください");
      return;
    }

    // 修正履歴をAPI保存
    if (correctionHistory.length > 0) {
      for (const correction of correctionHistory) {
        const tableIndex = 1; // 受注データ修正履歴テーブル
        await window.aivicApi.save(tableIndex, {
          修正項目名: correction.field,
          修正前値: correction.oldValue,
          修正後値: correction.newValue,
          修正理由: correction.reason,
          修正日時: correction.timestamp
        });
      }
    }

    // OCR結果をAPI保存
    const ocrTableIndex = 3; // AI_OCR読み込み結果テーブル
    await window.aivicApi.save(ocrTableIndex, {
      source_document_type: "受注書",
      extracted_fields: JSON.stringify(extractedFields),
      overall_confidence: Math.round(
        Object.values(currentOcrResult).reduce((a, b) => a + b.confidence, 0) / 
        Object.values(currentOcrResult).length
