function(container, apiUrl, tables) {
  let currentStep = 1;
  const maxStep = 4;

  // Step navigation
  function goToStep(step) {
    if (step < 1 || step > maxStep) return;

    // Hide all step contents
    document.querySelectorAll(".step-content").forEach(el => el.style.display = "none");
    document.querySelectorAll(".step-item").forEach(el => {
      el.style.opacity = "0.5";
      el.querySelector("div:first-child").style.background = "rgba(255,255,255,0.1)";
      el.querySelector("div:first-child").style.color = "var(--text-muted)";
    });

    // Show current step
    const stepContent = document.getElementById(`step-${step}-content`);
    if (stepContent) stepContent.style.display = "block";

    // Highlight current step
    const stepItem = document.querySelector(`.step-item[data-step="${step}"]`);
    if (stepItem) {
      stepItem.style.opacity = "1";
      stepItem.querySelector("div:first-child").style.background = "#ff6a00";
      stepItem.querySelector("div:first-child").style.color = "#fff";
    }

    // Update button visibility
    const prevBtn = container.querySelector("#btn-prev");
    const nextBtn = container.querySelector("#btn-next");
    const registerBtn = container.querySelector("#btn-register");

    prevBtn.style.display = step > 1 ? "block" : "none";
    nextBtn.style.display = step < maxStep ? "block" : "none";
    registerBtn.style.display = step === maxStep ? "block" : "none";

    currentStep = step;
  }

  // Event listeners
  container.querySelector("#btn-next").addEventListener("click", () => {
    goToStep(currentStep + 1);
  });

  container.querySelector("#btn-prev").addEventListener("click", () => {
    goToStep(currentStep - 1);
  });

  container.querySelector("#btn-register").addEventListener("click", async () => {
    const comment = container.querySelector("[data-testid='approval-comment']").value;
    if (!comment.trim()) {
      alert("承認コメントを入力してください");
      return;
    }

    // Simulate registration
    alert("受注ORD-2025-001234を基幹システムに登録しました。");
    window.showScreen("scr-1781413262699"); // Go to dashboard
  });

  container.querySelector("[data-testid='cancel-button']").addEventListener("click", () => {
    if (confirm("この画面を閉じますか？")) {
      window.showScreen("scr-1781413262699");
    }
  });

  // Step item click
  document.querySelectorAll(".step-item").forEach(item => {
    item.addEventListener("click", () => {
      const step = parseInt(item.dataset.step);
      if (step <= currentStep) goToStep(step);
    });
  });

  // Initialize
  goToStep(1);
}

