        await renderDetailView(selectedGroupId);
      }
    });
  }

  // 詳細照合ビューを描画する関数
  async function renderDetailView(groupId) {
    const group = allDuplicateGroups.find(g => g.重複受注検出結果ID === groupId);
    if (!group) return;

    // 主受注と副受注のデータを取得（ここではサンプルデータを使用）
    const mainOrder = {
      受注ID: group.主受注ID,
      顧客名: "株式会社ABC",
      顧客電話: "090-1234-5678",
      受注金額: "150,000",
      受注数量: "10",
      受注日時: "2025-01-15 10:30",
      チャネル: "Web注文"
    };

    const subOrder = {
      受注ID: group.副受注ID,
      顧客名: "株式会社ABC",
      顧客電話: "090-1234-5678",
      受注金額: "150,000",
      受注数量: "10",
      受注日時: "2025-01-15 10:35",
      チャネル: "電話受注"
    };

    // 差分を検出
    const differences = [];
    for (const key in mainOrder) {
      if (mainOrder[key] !== subOrder[key]) {
        differences.push({ field: key, main: mainOrder[key], sub: subOrder[key] });
      }
    }

    detailPanel.innerHTML = `
      <div style="background: var(--bg-card); padding: 12px 16px; border-radius: 6px; margin-bottom: 16px;">
        <div style="font-size: 13px; font-weight: 600; color: var(--text); margin-bottom: 8px;">
          重複判定情報
        </div>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px; font-size: 12px;">
          <div>
            <span style="color: var(--text-muted);">検出ルール:</span>
            <span style="color: var(--text); margin-left: 8px;">${group.検出ルールID}</span>
          </div>
          <div>
            <span style="color: var(--text-muted);">マッチング信頼度:</span>
            <span style="color: var(--text); margin-left: 8px; font-weight: 600;">${group.マッチング信頼度}%</span>
          </div>
          <div style="grid-column: 1 / -1;">
            <span style="color: var(--text-muted);">マッチング理由:</span>
            <span style="color: var(--text); margin-left: 8px;">${group.マッチング理由}</span>
          </div>
        </div>
      </div>

      <div style="background: var(--bg-card); padding: 12px 16px; border-radius: 6px; margin-bottom: 16px;">
        <div style="font-size: 13px; font-weight: 600; color: var(--text); margin-bottom: 12px;">
          受注データ比較
        </div>
        <table data-testid="comparison-table" style="width: 100%; border-collapse: collapse; font-size: 12px;">
          <thead>
            <tr style="border-bottom: 1px solid var(--border);">
              <th style="padding: 8px; text-align: left; color: var(--text); font-weight: 600; background: rgba(0,0,0,0.2);">項目</th>
              <th style="padding: 8px; text-align: left; color: var(--text); font-weight: 600; background: rgba(0,0,0,0.2);">主受注</th>
              <th style="padding: 8px; text-align: left; color: var(--text); font-weight: 600; background: rgba(0,0,0,0.2);">副受注</th>
            </tr>
          </thead>
          <tbody>
            ${Object.keys(mainOrder).map(key => {
              const isDiff = differences.some(d => d.field === key);
              const bgColor = isDiff ? 'rgba(255, 152, 0, 0.1)' : 'transparent';
              return `
                <tr style="border-bottom: 1px solid var(--border); background: ${bgColor};">
                  <td style="padding: 8px; color: var(--text-muted);">${key}</td>
                  <td style="padding: 8px; color: var(--text); ${isDiff ? 'font-weight: 600;' : ''}">${mainOrder[key]}</td>
                  <td style="padding: 8px; color: var(--text); ${isDiff ? 'font-weight: 600;' : ''}">${subOrder[key]}</td>
                </tr>
              `;
            }).join("")}
          </tbody>
        </table>
      </div>

      <div style="background: var(--bg-card); padding: 12px 16px; border-radius: 6px; margin-bottom: 16px;">
        <div style="font-size: 13px; font-weight: 600; color: var(--text); margin-bottom: 12px;">
          修正提案
        </div>
        <div style="background: rgba(76, 175, 80, 0.1); padding: 10px; border-left: 3px solid #4caf50; border-radius: 4px; font-size: 12px; color: var(--text); margin-bottom: 12px;">
          <strong>推奨対応:</strong> 両受注を統合し、主受注を確定。副受注は削除。
        </div>
      </div>

      <div style="background: var(--bg-card); padding: 12px 16px; border-radius: 6px; margin-bottom: 16px;">
        <div style="font-size: 13px; font-weight: 600; color: var(--text); margin-bottom: 12px;">
          対応方針
        </div>
        <div style="display: flex; flex-direction: column; gap: 8px;">
          <div>
            <label style="font-size: 12px; color: var(--text-muted); display: block; margin-bottom: 4px;">対応方針を選択</label>
            <select data-testid="action-policy" style="width: 100%; padding: 6px 8px; border: 1px solid rgba(255,255,255,0.18); background: rgba(0,0,0,0.25); color: var(--text); border-radius: 4px; font-size: 12px;">
              <option value="">選択してください</option>
              <option value="統合">統合（主受注を確定、副受注を削除）</option>
              <option value="分離">分離（別の受注として扱う）</option>
              <option value="保留">保留（後で判定）</option>
              <option value="却下">却下（誤検出）</option>
            </select>
          </div>

          <div>
            <label style="font-size: 12px; color: var(--text-muted); display: block; margin-bottom: 4px;">修正理由</label>
            <textarea data-testid="correction-reason" placeholder="修正理由を入力してください" style="width: 100%; padding: 8px; border: 1px solid rgba(255,255,255,0.18); background: rgba(0,0,0,0.25); color: var(--text); border-radius: 4px; font-size: 12px; resize: vertical; min-height: 60px;"></textarea>
          </div>

          <div>
            <label style="font-size: 12px; color: var(--text-muted); display: block; margin-bottom: 4px;">備考</label>
            <textarea data-testid="correction-notes" placeholder="備考を入力してください" style="width: 100%; padding: 8px; border: 1px solid rgba(255,255,255,0.18); background: rgba(0,0,0,0.25); color: var(--text); border-radius: 4px; font-size: 12px; resize: vertical; min-height: 60px;"></textarea>
          </div>
        </div>
      </div>

      <div style="display: flex; gap: 8px; margin-bottom: 16px;">
        <button data-testid="save-correction" class="action-btn" style="flex: 1;">修正内容を保存</button>
        <button data-testid="cancel-correction" class="action-btn secondary" style="flex: 1;">キャンセル</button>
      </div>
    `;

    emptyState.style.display = "none";
    detailPanel.style.display = "block";

    // 修正内容保存ボタンのイベント
    detailPanel.querySelector("[data-testid='save-correction']").addEventListener("click", async () => {
      const policy = detailPanel.querySelector("[data-testid='action-policy']").value;
      const reason = detailPanel.querySelector("[data-testid='correction-reason']").value;
      const notes = detailPanel.querySelector("[data-testid='correction-notes']").value;

      if (!policy) {
        alert("対応方針を選択してください");
        return;
      }

      if (!reason) {
        alert("修正理由を入力してください");
        return;
      }

      // 修正内容を保存（API呼び出し）
      const correctionData = {
        重複受注検出結果ID: groupId,
        対応方針: policy,
        修正理由: reason,
        備考: notes,
        確認者ID: "current-user-id",
        確認日時: new Date().toISOString()
      };

      const saved = await window.aivicApi.update(duplicateTableIndex, groupId, correctionData);
      if (saved) {
        alert("修正内容を保存しました");
        // 一覧を再読み込み
        await loadDuplicateGroups();
        emptyState.style.display = "flex";
        detailPanel.style.display = "none";
        selectedGroupId = null;
      }
    });

    // キャンセルボタンのイベント
    detailPanel.querySelector("[data-testid='cancel-correction']").addEventListener("click", () => {
      emptyState.style.display = "flex";
      detailPanel.style.display = "none";
      selectedGroupId = null;
      document.querySelectorAll(".group-item").forEach(item => {
        item.style.background = 'var(--bg-main)';
      });
    });
  }

  // 重複グループを読み込む関数
  async function loadDuplicateGroups() {
    const groups = await window.aivicApi.list(duplicateTableIndex);
    if (!groups) return;

    allDuplicateGroups = groups;
    applyFilters();
  }

  // フィルターを適用する関数
  function applyFilters() {
    let filtered = [...allDuplicateGroups];

    const status = statusFilter.value;
    if (status) {
      filtered = filtered.filter(g => g.検出ステータス === status);
    }

    const confidence = confidenceFilter.value;
    if (confidence) {
      const [min, max] = confidence.split('-').map(Number);
      filtered = filtered.filter(g => g.マッチング信頼度 >= min && g.マッチング信頼度 <= max);
    }

    const keyword = searchKeyword.value.toLowerCase();
    if (keyword) {
      filtered = filtered.filter(g =>
        g.主受注ID.toLowerCase().includes(keyword) ||
        g.副受注ID.toLowerCase().includes(keyword) ||
        g.マッチング理由.toLowerCase().includes(keyword)
      );
    }

    groupCount.textContent = filtered.length;
    renderGroupList(filtered);
  }

  // 検索ボタンのイベント
  searchBtn.addEventListener("click", applyFilters);

  // リセットボタンのイベント
  resetBtn.addEventListener("click", () => {
    statusFilter.value = "";
    confidenceFilter.value = "";
    searchKeyword.value = "";
    applyFilters();
  });

  // フィルター変更時のイベント
  statusFilter.addEventListener("change", applyFilters);
  confidenceFilter.addEventListener("change", applyFilters);
  searchKeyword.addEventListener("keyup", applyFilters);

  // 初期データ読み込み
  loadDuplicateGroups();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#validation-tbody");
  const resultCount = container.querySelector("#result-count");
  const footerInfo = container.querySelector("#footer-info");
  const detailModal = container.querySelector("#detail-modal");
  const detailContent = container.querySelector("#detail-content");
  const detailEditBtn = container.querySelector("#btn-detail-edit");
  const detailCloseBtn = container.querySelector("#btn-detail-close");

  let allRows = [];
  let selectedRowId = null;

  // ステータスバッジ色
  function getStatusBadgeStyle(status) {
    const styles = {
      "合格": "background: rgba(76, 175, 80, 0.2); color: #4CAF50; border-left: 3px solid #4CAF50;",
      "不合格": "background: rgba(244, 67, 54, 0.2); color: #F44336; border-left: 3px solid #F44336;",
      "警告": "background: rgba(255, 152, 0, 0.2); color: #FF9800; border-left: 3px solid #FF9800;",
      "保留": "background: rgba(158, 158, 158, 0.2); color: #9E9E9E; border-left: 3px solid #9E9E9E;"
    };
    return styles[status] || "background: var(--bg-card); color: var(--text);";
  }

  function getSeverityBadgeStyle(severity) {
    const styles = {
      "致命的": "background: rgba(244, 67, 54, 0.15); color: #F44336;",
      "高": "background: rgba(255, 152, 0, 0.15); color: #FF9800;",
      "中": "background: rgba(33, 150, 243, 0.15); color: #2196F3;",
      "低": "background: rgba(76, 175, 80, 0.15); color: #4CAF50;"
    };
    return styles[severity] || "background: var(--bg-card); color: var(--text);";
  }

  // 信頼度スコアバー
  function renderConfidenceBar(score) {
    const percentage = Math.max(0, Math.min(100, score || 0));
    const color = percentage >= 80 ? "#4CAF50" : percentage >= 60 ? "#FF9800" : "#F44336";
    return `<div style="display: flex; align-items: center; gap: 6px;">
      <div style="width: 50px; height: 6px; background: rgba(255,255,255,0.1); border-radius: 3px; overflow: hidden;">
        <div style="width: ${percentage}%; height: 100%; background: ${color};"></div>
      </div>
      <span style="font-size: 12px; color: var(--text-muted);">${percentage}%</span>
    </div>`;
  }

  // テーブル再描画
  function renderRows(rows) {
    allRows = rows;
    resultCount.textContent = `検索結果: ${rows.length}件`;

    if (rows.length === 0) {
      tbody.innerHTML = `<tr style="background: var(--bg-main); border-bottom: 1px solid var(--border);"><td colspan="9" style="padding: 20px; text-align: center; color: var(--text-muted);">検証結果がありません</td></tr>`;
      return;
    }

    tbody.innerHTML = rows.map(r => {
      const status = r.検証ステータス || "保留";
      const channel = r.チャネル || "—";
      const errorCode = r.エラーコード || "—";
      const errorMsg = r.エラーメッセージ || "—";
      const severity = r.重要度 || "中";
      const responseStatus = r.対応状況 || "未対応";
      const score = r.信頼度スコア || 0;

      return `<tr data-id="${r.id}" style="background: var(--bg-main); border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.2s;" onmouseover="this.style.background='var(--bg-card)'" onmouseout="this.style.background='var(--bg-main)'">
        <td style="padding: 10px 12px; color: var(--text); font-family: monospace; font-size: 12px;">${(r.受注データID || r.id || "").substring(0, 8)}</td>
