        </td>
        <td style="padding: 10px 12px; color: var(--text); font-size: 12px;">${channel}</td>
        <td style="padding: 10px 12px;">${renderConfidenceBar(score)}</td>
        <td style="padding: 10px 12px; color: var(--text); font-family: monospace; font-size: 12px;">${errorCode}</td>
        <td style="padding: 10px 12px; color: var(--text); font-size: 12px; max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${errorMsg}">${errorMsg}</td>
