          <div style="padding: 4px 8px; border-radius: 3px; font-size: 12px; font-weight: 500; ${getSeverityBadgeStyle(severity)}">${severity}</div>
        </td>
        <td style="padding: 10px 12px; color: var(--text); font-size: 12px;">${responseStatus}</td>
