  // 初期データ読み込み
  if (tables[0] && tables[0].records) {
    renderRows(tables[0].records);
  }

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const status = container.querySelector("#filter-status").value;
    const channel = container.querySelector("#filter-channel").value;
    const dateFrom = container.querySelector("#filter-date-from").value;
    const dateTo = container.querySelector("#filter-date-to").value;
    const keyword = container.querySelector("#input-search").value.toLowerCase();

    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const filtered = rows.filter(r => {
      if (status && r.検証ステータス !== status) return false;
      if (channel && r.チャネル !== channel) return false;
      if (dateFrom && new Date(r.検証実行日時) < new Date(dateFrom)) return false;
      if (dateTo && new Date(r.検証実行日時) > new Date(dateTo + "T23:59:59")) return false;
      if (keyword && !JSON.stringify(r).toLowerCase().includes(keyword)) return false;
      return true;
    });

    renderRows(filtered);
