function(container, apiUrl, tables) {
  // グラフ描画関数
  function drawChannelErrorChart() {
    const canvas = container.querySelector("#chart-channel-errors");
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    const channels = ["Web注文", "電話受注", "店舗POS", "API連携"];
    const errorRates = [7.1, 12.4, 9.3, 5.8];
    const barWidth = canvas.width / (channels.length * 1.5);
    const maxHeight = canvas.height * 0.8;
    const maxRate = 15;

    ctx.fillStyle = "#9fb0d1";
    ctx.font = "12px sans-serif";
    ctx.textAlign = "center";

    channels.forEach((ch, i) => {
      const x = 40 + i * (barWidth + 20);
      const height = (errorRates[i] / maxRate) * maxHeight;
      const y = canvas.height - 40 - height;

      // バー
      ctx.fillStyle = i === 1 ? "#e74c3c" : (i === 2 ? "#f39c12" : "#3498db");
      ctx.fillRect(x, y, barWidth, height);

      // ラベル
      ctx.fillStyle = "#9fb0d1";
      ctx.fillText(ch, x + barWidth / 2, canvas.height - 10);
      ctx.fillText(errorRates[i] + "%", x + barWidth / 2, y - 5);
    });

    // Y軸
    ctx.strokeStyle = "rgba(159,176,209,0.3)";
    ctx.beginPath();
    ctx.moveTo(30, 20);
    ctx.lineTo(30, canvas.height - 40);
    ctx.stroke();
  }

  function drawValidationBreakdownChart() {
    const canvas = container.querySelector("#chart-validation-breakdown");
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    const data = [
      { label: "合格", value: 1110, color: "#27ae60" },
      { label: "不合格", value: 93, color: "#e74c3c" },
      { label: "警告", value: 35, color: "#f39c12" },
      { label: "保留", value: 9, color: "#9b59b6" }
    ];
    const total = data.reduce((s, d) => s + d.value, 0);

    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const radius = Math.min(canvas.width, canvas.height) / 3;

    let startAngle = -Math.PI / 2;
    data.forEach(d => {
      const sliceAngle = (d.value / total) * 2 * Math.PI;
      ctx.fillStyle = d.color;
      ctx.beginPath();
      ctx.arc(centerX, centerY, radius, startAngle, startAngle + sliceAngle);
      ctx.lineTo(centerX, centerY);
      ctx.fill();
      startAngle += sliceAngle;
    });

    // 凡例
    ctx.font = "12px sans-serif";
    ctx.fillStyle = "#9fb0d1";
    ctx.textAlign = "left";
    data.forEach((d, i) => {
      ctx.fillStyle = d.color;
      ctx.fillRect(20, 20 + i * 20, 12, 12);
      ctx.fillStyle = "#9fb0d1";
      ctx.fillText(d.label + " (" + d.value + "件)", 40, 28 + i * 20);
    });
  }

  // 初期データ描画
  function renderInitial() {
    drawChannelErrorChart();
    drawValidationBreakdownChart();
  }

  // フィルタ適用
  container.querySelector("[data-testid='filter-button']").addEventListener("click", () => {
    const period = container.querySelector("[data-testid='period-select']").value;
    const channel = container.querySelector("[data-testid='channel-filter']").value;
    const user = container.querySelector("[data-testid='user-filter']").value;
    const status = container.querySelector("[data-testid='status-filter']").value;
    console.log("フィルタ適用:", { period, channel, user, status });
    // 実際のフィルタリング処理はここに実装
  });

  // CSVエクスポート
  container.querySelector("[data-testid='export-csv-button']").addEventListener("click", () => {
    const headers = ["チャネル", "総件数", "合格", "不合格", "警告", "保留", "エラー率", "平均スコア"];
    const rows = [
      ["Web注文", "450", "405", "32", "10", "3", "7.1%", "89.2"],
      ["電話受注", "380", "330", "35", "12", "3", "12.4%", "86.8"],
      ["店舗POS", "280", "252", "18", "8", "2", "9.3%", "88.5"],
      ["API連携", "137", "123", "8", "5", "1", "5.8%", "91.3"],
      ["合計", "1247", "1110", "93", "35", "9", "8.9%", "87.4"]
    ];
    const csv = "\uFEFF" + headers.join(",") + "\n" + rows.map(r => r.join(",")).join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "集計結果_" + new Date().toISOString().slice(0, 10) + ".csv";
    link.click();
  });

  // 詳細ダッシュボードへ遷移
  container.querySelector("[data-testid='detail-dashboard-button']").addEventListener("click", () => {
    window.showScreen("scr-1781413919709");
  });

  // 初期描画
  renderInitial();
}

function(container, apiUrl, tables) {
  const orderListTbody = container.querySelector("#order-list-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const emptyState = container.querySelector("#empty-state");
  const detailHeader = container.querySelector("#detail-header");
  const statusFilter = container.querySelector("[data-testid='status-filter']");
  const scoreFilter = container.querySelector("[data-testid='score-filter']");
  const searchBtn = container.querySelector("[data-testid='search-button']");
  const approvalResult = container.querySelector("#approval-result");
  const approvalReason = container.querySelector("#approval-reason");
  const btnApprove = container.querySelector("#btn-approve");
  const btnReject = container.querySelector("#btn-reject");
  const btnCancel = container.querySelector("#btn-cancel");

  let currentOrderId = null;
  let allOrders = [];

  // 1. 受注一覧を再描画する関数
  function renderOrderList(orders) {
    orderListTbody.innerHTML = orders.map(order => {
      const scoreClass = order.信頼度スコア >= 80 ? 'high' : order.信頼度スコア >= 50 ? 'medium' : 'low';
      const scoreColor = scoreClass === 'high' ? 'var(--primary)' : scoreClass === 'medium' ? '#f59e0b' : '#ef4444';
      return `
        <tr data-id="${order.id}" class="order-row" style="cursor: pointer; border-bottom: 1px solid var(--border); transition: background 0.2s;">
          <td style="padding: 8px 10px; border-right: 1px solid var(--border); color: var(--text); font-weight: 500;">${order.受注ID || '-'}</td>
          <td style="padding: 8px 10px; border-right: 1px solid var(--border); color: var(--text);">${order.顧客名 || '-'}</td>
          <td style="padding: 8px 10px; border-right: 1px solid var(--border); color: var(--text); text-align: right;">${order.受注金額 ? '¥' + order.受注金額.toLocaleString() : '-'}</td>
          <td style="padding: 8px 10px; border-right: 1px solid var(--border); color: ${scoreColor}; text-align: center; font-weight: 600;">${order.信頼度スコア || 0}</td>
          <td style="padding: 8px 10px; text-align: center;">
            <span style="display: inline-block; padding: 3px 8px; border-radius: 3px; font-size: 11px; font-weight: 500; background: ${order.検証ステータス === '待機中' ? 'rgba(59,130,246,0.2)' : 'rgba(107,114,128,0.2)'}; color: ${order.検証ステータス === '待機中' ? '#3b82f6' : '#6b7280'};">${order.検証ステータス || '未確認'}</span>
          </td>
        </tr>
      `;
    }).join("");

    // 行クリックイベント
    container.querySelectorAll(".order-row").forEach(row => {
      row.addEventListener("click", () => {
        const orderId = row.dataset.id;
        showOrderDetail(orderId);
        // 選択行をハイライト
        container.querySelectorAll(".order-row").forEach(r => r.style.background = "");
        row.style.background = "rgba(59,130,246,0.1)";
      });
    });
  }

  // 2. 受注詳細を表示する関数
  function showOrderDetail(orderId) {
    const order = allOrders.find(o => o.id === orderId);
    if (!order) return;

    currentOrderId = orderId;
    detailHeader.textContent = `受注ID: ${order.受注ID} | ${order.顧客名}`;

    // 基本情報を設定
    container.querySelector("#detail-order-id").textContent = order.受注ID || '-';
    container.querySelector("#detail-customer").textContent = order.顧客名 || '-';
    container.querySelector("#detail-amount").textContent = order.受注金額 ? '¥' + order.受注金額.toLocaleString() : '-';
    container.querySelector("#detail-channel").textContent = order.チャネル || '-';
    container.querySelector("#detail-date").textContent = order.受注日時 ? new Date(order.受注日時).toLocaleString('ja-JP') : '-';
    container.querySelector("#detail-score").textContent = (order.信頼度スコア || 0) + ' / 100';

    // 検出された問題を表示
    const issuesContainer = container.querySelector("#issues-container");
    const issues = order.検出された問題 ? (Array.isArray(order.検出された問題) ? order.検出された問題 : [order.検出された問題]) : [];
    issuesContainer.innerHTML = issues.length > 0 
      ? issues.map(issue => `
          <div style="padding: 8px 10px; border-left: 3px solid #ef4444; background: rgba(239,68,68,0.1); border-radius: 3px; font-size: 12px;">
            <div style="color: #ef4444; font-weight: 600; margin-bottom: 2px;">${issue.エラーコード || 'ERROR'}</div>
            <div style="color: var(--text);">${issue.エラーメッセージ || issue}</div>
            <div style="color: var(--text-muted); font-size: 11px; margin-top: 4px;">重要度: ${issue.重要度 || '中'}</div>
          </div>
        `).join("")
      : '<div style="color: var(--text-muted); font-size: 12px;">問題は検出されていません</div>';

    // 入力漏れ項目を表示
    const missingContainer = container.querySelector("#missing-items-container");
    const missing = order.入力漏れ項目 ? (Array.isArray(order.入力漏れ項目) ? order.入力漏れ項目 : [order.入力漏れ項目]) : [];
    missingContainer.innerHTML = missing.length > 0
      ? missing.map(item => `
          <div style="padding: 6px 10px; background: rgba(245,158,11,0.1); border-left: 3px solid #f59e0b; border-radius: 3px; font-size: 12px; color: var(--text);">
            ${item.漏れ項目名 || item} <span style="color: var(--text-muted); font-size: 11px;">(${item.漏れ項目区分 || '必須'})</span>
          </div>
        `).join("")
      : '<div style="color: var(--text-muted); font-size: 12px;">入力漏れはありません</div>';

    // チャネル間矛盾を表示
    const conflictContainer = container.querySelector("#channel-conflicts-container");
    const conflicts = order.チャネル間矛盾内容 ? (Array.isArray(order.チャネル間矛盾内容) ? order.チャネル間矛盾内容 : [order.チャネル間矛盾内容]) : [];
    conflictContainer.innerHTML = conflicts.length > 0
      ? conflicts.map(conflict => `
          <div style="padding: 8px 10px; background: rgba(239,68,68,0.05); border-left: 3px solid #f97316; border-radius: 3px; font-size: 12px;">
            <div style="color: #f97316; font-weight: 600; margin-bottom: 2px;">${conflict.矛盾タイプ || '矛盾'}</div>
            <div style="color: var(--text);">${conflict.矛盾内容 || conflict}</div>
          </div>
        `).join("")
      : '<div style="color: var(--text-muted); font-size: 12px;">矛盾は検出されていません</div>';

    // フォームをリセット
    approvalResult.value = "";
    approvalReason.value = "";

    // パネルを表示
    emptyState.style.display = "none";
    detailPanel.style.display = "block";
  }

  // 3. 初期データを読み込んで表示
  window.aivicApi.list(0).then(rows => {
    allOrders = rows || tables[0].records || [];
    renderOrderList(allOrders);
  });

  // 4. 検索ボタンのイベントリスナー
  searchBtn.addEventListener("click", () => {
    const status = statusFilter.value;
    const minScore = parseInt(scoreFilter.value) || 0;

    const filtered = allOrders.filter(order => {
      const matchStatus = !status || order.検証ステータス === status;
      const matchScore = (order.信頼度スコア || 0) >= minScore;
      return matchStatus && matchScore;
    });

    renderOrderList(filtered);
  });

  // 5. 承認ボタンのイベントリスナー
  btnApprove.addEventListener("click", async () => {
    if (!currentOrderId) return;
    if (!approvalResult.value) {
      alert("判定結果を選択してください");
      return;
    }

    const flowData = {
      受注データ_ID: currentOrderId,
      フロー段階: "最終承認",
      現在ステータス: "承認済",
      承認判定: approvalResult.value,
      承認コメント: approvalReason.value,
      承認日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(1, flowData); // テーブルインデックス 1 = 連携承認フロー
    if (saved) {
      alert("承認しました");
      // 一覧を再読み込み
      window.aivicApi.list(0).then(rows => {
        allOrders = rows || [];
        renderOrderList(allOrders);
        emptyState.style.display = "flex";
        detailPanel.style.display = "none";
        currentOrderId = null;
      });
    }
  });

  // 6. 差戻しボタンのイベントリスナー
  btnReject.addEventListener("click", async () => {
    if (!currentOrderId) return;
    if (!approvalReason.value) {
      alert("差戻し理由を入力してください");
      return;
    }

    const flowData = {
      受注データ_ID: currentOrderId,
      フロー段階: "最終承認",
      現在ステータス: "差戻し",
      承認判定: "差戻し",
      承認コメント: approvalReason.value,
      承認日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(1, flowData);
    if (saved) {
      alert("差戻ししました");
      window.aivicApi.list(0).then(rows => {
        allOrders = rows || [];
        renderOrderList(allOrders);
        emptyState.style.display = "flex";
        detailPanel.style.display = "none";
        currentOrderId = null;
      });
    }
  });

  // 7. キャンセルボタンのイベントリスナー
  btnCancel.addEventListener("click", () => {
    emptyState.style.display = "flex";
    detailPanel.style.display = "none";
    currentOrderId = null;
    container.querySelectorAll(".order-row").forEach(r => r.style.background = "");
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const TABLE_MODIFY_HISTORY = 0;      // 受注データ修正履歴
  const TABLE_VALIDATION_RESULT = 1;   // 受注データ検証結果
