      チャネルID: "WEB"
    };

    // 修正前データを保存
    container.querySelector("#order-data-json").value = JSON.stringify(orderRecord);
    container.querySelector("#before-data-json").value = JSON.stringify(orderRecord);

    // 修正後データ（初期値は修正前と同じ）
