  // ========== 5. 検証結果表示 ==========
  async function displayValidationResults(orderId) {
    // 修正前検証結果（サンプル）
    const beforeValidation = tables[1]?.records?.filter(r => r.受注データID === orderId) || [
      { 検証ステータス: "不合格", エラーコード: "ERR001", エラーメッセージ: "受注金額が不正な形式です", 重要度: "高" },
      { 検証ステータス: "警告", エラーコード: "WARN001", エラーメッセージ: "配送先が不完全です", 重要度: "中" }
    ];

    const beforeHtml = beforeValidation.map(v => `
      <div style="padding: 6px 0; border-left: 3px solid #ff6a00; padding-left: 8px; margin-bottom: 6px;">
        <div style="font-size: 11px; color: #ff6a00; font-weight: 500;">${v.エラーコード} (${v.重要度})</div>
        <div style="font-size: 12px; color: var(--text);">${v.エラーメッセージ}</div>
      </div>
    `).join("");
    container.querySelector("#before-validation-display").innerHTML = beforeHtml || "<div style='color: var(--text-muted);'>検証エラーなし</div>";

    // 修正後検証結果（修正により改善されたと仮定）
    const afterValidation = [
      { 検証ステータス: "合格", エラーコード: "OK", エラーメッセージ: "すべての検証に合格しました", 重要度: "低" }
    ];

    const afterHtml = afterValidation.map(v => `
      <div style="padding: 6px 0; border-left: 3px solid #4ade80; padding-left: 8px; margin-bottom: 6px;">
        <div style="font-size: 11px; color: #4ade80; font-weight: 500;">${v.エラーコード}</div>
        <div style="font-size: 12px; color: var(--text);">${v.エラーメッセージ}</div>
      </div>
    `).join("");
    container.querySelector("#after-validation-display").innerHTML = afterHtml;

    // 信頼度スコア表示
    const scoreRecord = tables[2]?.records?.find(r => r.受注データID === orderId) || {
      総合スコア: 45,
      完全性スコア: 60,
      正確性スコア: 35,
      一貫性スコア: 40
    };
    container.querySelector("#score-before-display").textContent = scoreRecord.総合スコア || "-";
    container.querySelector("#total-score-display").textContent = scoreRecord.総合スコア || "-";

    // 修正項目一覧
    const modifyItems = [
      "受注金額",
      "配送先住所",
      "顧客電話番号"
    ];
    const itemsHtml = modifyItems.map(item => `
      <div style="padding: 4px 0; color: var(--text);">• ${item}</div>
    `).join("");
    container.querySelector("#modify-items-list").innerHTML = itemsHtml;
  }

  // ========== 6. 修正後スコア計算 ==========
  function updateTotalScore() {
    const scoreAfter = parseInt(container.querySelector("#score-after").value) || 0;
    container.querySelector("#total-score-display").textContent = scoreAfter;
  }

  // ========== 7. 保存処理 ==========
  async function saveModifyHistory() {
    const reason = container.querySelector("#modify-reason").value;
    const notes = container.querySelector("#modify-notes").value;
    const scoreAfter = parseInt(container.querySelector("#score-after").value) || 0;

    if (!reason) {
      alert("修正理由を選択してください");
      return;
    }

    const orderId = container.querySelector("#order-id-display").textContent;
    const beforeData = JSON.parse(container.querySelector("#before-data-json").value);
    const afterData = JSON.parse(container.querySelector("#after-data-json").value);

    // 修正項目を抽出
    const modifyItems = [];
    Object.keys(beforeData).forEach(key => {
      if (beforeData[key] !== afterData[key]) {
        modifyItems.push({
          修正項目名: key,
          修正前値: beforeData[key],
          修正後値: afterData[key]
        });
      }
    });

    // 修正履歴レコード作成
    const historyRecord = {
      修正履歴ID: "hist-" + Math.random().toString(36).substr(2, 9),
      受注データID: orderId,
      修正項目名: modifyItems.map(m => m.修正項目名).join(", "),
      修正前値: JSON.stringify(beforeData),
      修正後値: JSON.stringify(afterData),
      修正理由: reason,
      修正備考: notes,
      修正ユーザーID: currentUserId,
      修正日時: new Date().toISOString(),
      作成日時: new Date().toISOString()
    };

    // API 保存
    const saved = await window.aivicApi.save(TABLE_MODIFY_HISTORY, historyRecord);

    if (saved) {
      alert("修正履歴を保存しました");
      // 修正対象優先度リスト画面へ遷移
      window.showScreen("scr-1781413354977");
    } else {
      alert("保存に失敗しました");
    }
  }

  // ========== 8. イベントリスナー登録 ==========
  container.querySelector("#score-after").addEventListener("input", updateTotalScore);

  container.querySelector("#btn-save").addEventListener("click", saveModifyHistory);

  container.querySelector("#btn-cancel").addEventListener("click", () => {
    if (confirm("修正内容を破棄して戻りますか？")) {
      window.showScreen("scr-1781413282852");
    }
  });

  // ========== 9. 初期化実行 ==========
  initializeScreen();
}

function(container, apiUrl, tables) {
