    "警告": "#fbbf24",
    "保留": "#9ca3af"
  };

  // 重要度色マッピング
  const severityColorMap = {
    "致命的": "#dc2626",
    "高": "#f97316",
    "中": "#eab308",
    "低": "#6b7280"
  };

  // テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const statusColor = statusColorMap[r.検証ステータス] || "#9ca3af";
      const severityColor = severityColorMap[r.重要度] || "#9ca3af";
      const scoreNum = parseInt(r.信頼度スコア) || 0;
      const scoreColor = scoreNum >= 80 ? "#4ade80" : scoreNum >= 60 ? "#fbbf24" : "#f87171";

      return `
        <tr 
          data-id="${r.id || ''}" 
          style="border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.15s;"
          onmouseover="this.style.background='rgba(255,255,255,0.04)'"
          onmouseout="this.style.background='transparent'"
        >
          <td style="padding: 8px 12px; color: var(--text); word-break: break-all;">${r.受注ID || '-'}</td>
          <td style="padding: 8px 12px; color: var(--text); white-space: nowrap;">${r.受注日時 ? new Date(r.受注日時).toLocaleString('ja-JP') : '-'}</td>
          <td style="padding: 8px 12px; color: var(--text);">${r.チャネル || '-'}</td>
          <td style="padding: 8px 12px;">
            <span style="display: inline-block; padding: 2px 8px; border-radius: 3px; background: ${statusColor}; color: #fff; font-size: 11px; font-weight: 600;">
              ${r.検証ステータス || '-'}
            </span>
          </td>
          <td style="padding: 8px 12px; text-align: center;">
            <div style="display: flex; align-items: center; justify-content: center; gap: 6px;">
              <div style="width: 40px; height: 6px; background: rgba(255,255,255,0.1); border-radius: 3px; overflow: hidden;">
                <div style="width: ${scoreNum}%; height: 100%; background: ${scoreColor}; transition: width 0.3s;"></div>
              </div>
              <span style="color: var(--text); font-weight: 600; min-width: 30px;">${scoreNum}</span>
            </div>
          </td>
          <td style="padding: 8px 12px; color: var(--text); max-width: 120px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${r.検証結果 || ''}">${r.検証結果 || '-'}</td>
          <td style="padding: 8px 12px;">
            <span style="display: inline-block; padding: 2px 8px; border-radius: 3px; background: ${severityColor}; color: #fff; font-size: 11px; font-weight: 600;">
              ${r.重要度 || '-'}
            </span>
          </td>
          <td style="padding: 8px 12px; text-align: center;">
            <button 
              class="action-btn secondary detail-btn" 
              data-id="${r.id || ''}"
              style="background: transparent; color: var(--primary); border: 1px solid var(--primary); padding: 3px 8px; border-radius: 3px; font-size: 11px; cursor: pointer; margin-right: 4px;"
            >
              詳細
            </button>
            <button 
              class="action-btn secondary edit-btn" 
              data-id="${r.id || ''}"
              style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 3px 8px; border-radius: 3px; font-size: 11px; cursor: pointer; margin-right: 4px;"
            >
              修正
            </button>
            <button 
              class="action-btn secondary delete-btn" 
              data-id="${r.id || ''}"
              style="background: transparent; color: #f87171; border: 1px solid rgba(248,113,113,0.3); padding: 3px 8px; border-radius: 3px; font-size: 11px; cursor: pointer;"
            >
              削除
            </button>
          </td>
        </tr>
      `;
    }).join("");
    statusText.textContent = `${rows.length}件の受注データを表示中`;
  }

  // 初期データ読み込み
  if (tables && tables[0] && tables[0].records) {
    allRows = tables[0].records;
    renderRows(allRows);
  }

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const orderId = container.querySelector("#filter-order-id").value.trim();
    const dateFrom = container.querySelector("#filter-date-from").value;
    const dateTo = container.querySelector("#filter-date-to").value;
    const status = container.querySelector("#filter-status").value;
    const channel = container.querySelector("#filter-channel").value;
    const scoreMin = parseInt(container.querySelector("#filter-score-min").value) || 0;
    const scoreMax = parseInt(container.querySelector("#filter-score-max").value) || 100;
    const severity = container.querySelector("#filter-severity").value;

    const filtered = allRows.filter(r => {
      if (orderId && !r.受注ID?.includes(orderId)) return false;
      if (dateFrom && new Date(r.受注日時) < new Date(dateFrom)) return false;
      if (dateTo && new Date(r.受注日時) > new Date(dateTo + "T23:59:59")) return false;
      if (status && r.検証ステータス !== status) return false;
      if (channel && r.チャネル !== channel) return false;
      const score = parseInt(r.信頼度スコア) || 0;
      if (score < scoreMin || score > scoreMax) return false;
      if (severity && r.重要度 !== severity) return false;
      return true;
    });

    renderRows(filtered);
  });

  // リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#filter-order-id").value = "";
    container.querySelector("#filter-date-from").value = "";
    container.querySelector("#filter-date-to").value = "";
    container.querySelector("#filter-status").value = "";
    container.querySelector("#filter-channel").value = "";
    container.querySelector("#filter-score-min").value = "";
    container.querySelector("#filter-score-max").value = "";
    container.querySelector("#filter-severity").value = "";
    renderRows(allRows);
  });

  // CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", () => {
    if (allRows.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["受注ID", "受注日時", "チャネル", "検証ステータス", "信頼度スコア", "検証結果", "重要度"];
    const csvContent = [
      "\uFEFF" + headers.join(","),
      ...allRows.map(r => [
        `"${r.受注ID || ''}"`,
        `"${r.受注日時 ? new Date(r.受注日時).toLocaleString('ja-JP') : ''}"`,
        `"${r.チャネル || ''}"`,
        `"${r.検証ステータス || ''}"`,
        r.信頼度スコア || '0',
        `"${(r.検証結果 || '').replace(/"/g, '""')}"`,
        `"${r.重要度 || ''}"`
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `受注ステータス照会_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // ダッシュボードボタン
  container.querySelector("#btn-dashboard").addEventListener("click", () => {
    window.showScreen("scr-1781413262699");
  });

  // 行レベル操作（詳細・編集・削除）
  container.addEventListener("click", async e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      window.showScreen("scr-1781413282852", { orderId: id });
      return;
    }

    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      const id = editBtn.dataset.id;
      window.showScreen("scr-1781413686599", { orderId: id });
      return;
    }

    const delBtn = e.target.closest(".delete-btn");
    if (delBtn) {
      const id = delBtn.dataset.id;
      if (!confirm("この受注データを削除しますか？")) return;
      const result = await window.aivicApi.delete(0, id);
      if (result) {
        allRows = allRows.filter(r => r.id !== id);
        renderRows(allRows);
      }
      return;
    }
  });
}

function(container, apiUrl, tables) {
  const validationTbody = container.querySelector("#validation-tbody");
  const priorityTbody = container.querySelector("#priority-tbody");
  const detailPanel = container.querySelector("#detail-panel");

  const statusFilter = container.querySelector("[data-testid='status-filter']");
