  const severityFilter = container.querySelector("[data-testid='severity-filter']");
  const confidenceMinInput = container.querySelector("[data-testid='confidence-min']");
  const searchBtn = container.querySelector("[data-testid='search-button']");
  const exportBtn = container.querySelector("[data-testid='export-button']");

  // テーブルインデックスの推定
  let validationTableIdx = 0;  // 受注データ検証結果
  let priorityTableIdx = 1;    // 修正対象優先度リスト
  let duplicateTableIdx = 2;   // 重複受注検出結果
  let conflictTableIdx = 3;    // チャネル間矛盾検出結果
  let omissionTableIdx = 4;    // 入力漏れ検出結果
  let confidenceTableIdx = 5;  // 信頼度スコア

  // 1. 検証結果一覧の再描画
  function renderValidationRows(rows) {
