      return;
    }

    validationTbody.innerHTML = rows.map(r => {
      const statusColor = r.検証ステータス === "合格" ? "#4ade80" : r.検証ステータス === "不合格" ? "#ef4444" : r.検証ステータス === "警告" ? "#f59e0b" : "#6b7280";
      const severityBg = r.重要度 === "致命的" ? "rgba(239,68,68,0.15)" : r.重要度 === "高" ? "rgba(245,158,11,0.15)" : r.重要度 === "中" ? "rgba(59,130,246,0.15)" : "rgba(107,114,128,0.15)";

      return `<tr data-id="${r.検証結果ID || r.id}" style="background: var(--bg-main); border-bottom: 1px solid rgba(255,255,255,0.06); cursor: pointer; transition: background 0.15s;" onmouseover="this.style.background='rgba(255,255,255,0.04)'" onmouseout="this.style.background='var(--bg-main)'">
        <td style="padding: 8px 12px; color: var(--text); font-family: monospace; font-size: 11px;">${(r.受注データID || r.id || "").substring(0, 8)}</td>
        <td style="padding: 8px 12px; color: var(--text); font-size: 11px;">${r.チャネルコード || r.チャネル || "-"}</td>
        <td style="padding: 8px 12px; color: ${statusColor}; font-weight: 600; font-size: 11px;">${r.検証ステータス || "-"}</td>
        <td style="padding: 8px 12px; color: var(--text); font-size: 11px; max-width: 100px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${r.エラーメッセージ || r.エラー内容 || ""}">${r.エラーコード || r.エラー内容 || "-"}</td>
        <td style="padding: 8px 12px; text-align: center; color: var(--text); font-size: 11px; font-weight: 600;">${r.総合スコア || r.信頼度 || "-"}</td>
        <td style="padding: 8px 12px; text-align: center; color: var(--text); font-size: 11px;"><span style="background: rgba(239,68,68,0.15); color: #ef4444; padding: 2px 6px; border-radius: 2px; font-size: 10px;">●</span></td>
        <td style="padding: 8px 12px; text-align: center; color: var(--text); font-size: 11px;"><span style="background: rgba(245,158,11,0.15); color: #f59e0b; padding: 2px 6px; border-radius: 2px; font-size: 10px;">●</span></td>
        <td style="padding: 8px 12px; text-align: center; color: var(--text); font-size: 11px;"><span style="background: rgba(59,130,246,0.15); color: #3b82f6; padding: 2px 6px; border-radius: 2px; font-size: 10px;">●</span></td>
        <td style="padding: 8px 12px; text-align: center; color: var(--text); font-weight: 600; font-size: 11px; background: ${severityBg}; border-radius: 2px;">${r.重要度 || "-"}</td>
      </tr>`;
    }).join("");
  }

  // 2. 優先度リストの再描画
  function renderPriorityRows(rows) {
    if (!rows || rows.length === 0) {
      priorityTbody.innerHTML = `<tr style="background: var(--bg-main); border-bottom: 1px solid rgba(255,255,255,0.06);"><td colspan="6" style="padding: 12px; text-align: center; color: var(--text-muted); font-size: 11px;">修正対象がありません</td></tr>`;
      return;
    }

    priorityTbody.innerHTML = rows.slice(0, 8).map(r => {
      const priorityColor = r.優先度レベル === 1 ? "#ef4444" : r.優先度レベル === 2 ? "#f59e0b" : r.優先度レベル === 3 ? "#3b82f6" : "#6b7280";
      return `<tr style="background: var(--bg-main); border-bottom: 1px solid rgba(255,255,255,0.06);">
        <td style="padding: 6px 10px; text-align: center; color: #fff; background: ${priorityColor}; border-radius: 2px; font-weight: 600; font-size: 11px;">${r.優先度レベル || "-"}</td>
        <td style="padding: 6px 10px; color: var(--text); font-family: monospace; font-size: 10px;">${(r.受注データID || r.id || "").substring(0, 8)}</td>
        <td style="padding: 6px 10px; color: var(--text); font-size: 10px;">${r.エラー分類 || "-"}</td>
        <td style="padding: 6px 10px; color: var(--text-muted); font-size: 10px;">${r.割り当て先ユーザーID ? "割当済" : "未割当"}</td>
        <td style="padding: 6px 10px; text-align: center; color: var(--text); font-size: 10px;">${r.推定修正時間分 || "-"}分</td>
        <td style="padding: 6px 10px; color: var(--text); font-size: 10px;">${r.修正ステータス || "-"}</td>
      </tr>`;
    }).join("");
  }

  // 3. 詳細パネルの表示
  function showDetail(validationRow) {
    const html = `
      <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 8px; padding-bottom: 8px; border-bottom: 1px solid rgba(255,255,255,0.08);">
        <strong style="color: var(--text);">受注ID:</strong> ${(validationRow.受注データID || validationRow.id || "").substring(0, 12)}
      </div>
      <div style="font-size: 11px; margin-bottom: 6px;">
        <strong style="color: var(--text);">検証ステータス:</strong>
        <span style="color: ${validationRow.検証ステータス === "合格" ? "#4ade80" : validationRow.検証ステータス === "不合格" ? "#ef4444" : "#f59e0b"}; font-weight: 600;">${validationRow.検証ステータス || "-"}</span>
      </div>
      <div style="font-size: 11px; margin-bottom: 6px;">
        <strong style="color: var(--text);">検証項目:</strong>
        <span style="color: var(--text-muted);">${validationRow.検証項目 || "-"}</span>
      </div>
      <div style="font-size: 11px; margin-bottom: 6px;">
        <strong style="color: var(--text);">エラーコード:</strong>
        <span style="color: var(--text-muted); font-family: monospace;">${validationRow.エラーコード || "-"}</span>
      </div>
      <div style="font-size: 11px; margin-bottom: 6px;">
        <strong style="color: var(--text);">重要度:</strong>
        <span style="background: ${validationRow.重要度 === "致命的" ? "rgba(239,68,68,0.15)" : "rgba(245,158,11,0.15)"}; color: ${validationRow.重要度 === "致命的" ? "#ef4444" : "#f59e0b"}; padding: 2px 6px; border-radius: 2px; font-size: 10px; font-weight: 600;">${validationRow.重要度 || "-"}</span>
      </div>
      <div style="font-size: 11px; margin-bottom: 8px; padding: 8px; background: rgba(0,0,0,0.25); border-radius: 3px; border-left: 2px solid var(--primary);">
        <strong style="color: var(--text);">エラーメッセージ:</strong>
        <div style="color: var(--text-muted); margin-top: 4px; font-size: 10px; line-height: 1.4;">${validationRow.エラーメッセージ || "エラーメッセージなし"}</div>
      </div>
      <div style="font-size: 11px; margin-bottom: 6px;">
        <strong style="color: var(--text);">期待値:</strong>
        <div style="color: var(--text-muted); font-family: monospace; font-size: 10px; margin-top: 2px;">${validationRow.期待値 || "-"}</div>
      </div>
      <div style="font-size: 11px; margin-bottom: 8px;">
        <strong style="color: var(--text);">実際値:</strong>
        <div style="color: var(--text-muted); font-family: monospace; font-size: 10px; margin-top: 2px;">${validationRow.検証値 || "-"}</div>
      </div>
      <div style="font-size: 11px; margin-bottom: 6px;">
        <strong style="color: var(--text);">信頼度スコア:</strong>
        <span style="color: var(--primary); font-weight: 600;">${validationRow.総合スコア || validationRow.信頼度 || "-"}</span>
      </div>
      <div style="font-size: 11px; margin-bottom: 8px;">
        <strong style="color: var(--text);">対応状況:</strong>
        <span style="color: var(--text-muted);">${validationRow.対応状況 || "未対応"}</span>
      </div>
      <div style="display: flex; gap: 6px; margin-top: 12px;">
        <button class="action-btn" style="flex: 1; padding: 6px 8px; font-size: 11px;" onclick="window.showScreen('scr-1781413282852')">修正</button>
