      </div>
    `;
    detailPanel.innerHTML = html;
  }

  // 4. 初期データ読み込み
  async function loadData() {
    try {
      const validationRows = tables[validationTableIdx]?.records || [];
      const priorityRows = tables[priorityTableIdx]?.records || [];

      renderValidationRows(validationRows);
      renderPriorityRows(priorityRows);
    } catch (e) {
      console.error("データ読み込みエラー:", e);
    }
  }

  // 5. 検索フィルタリング
  searchBtn.addEventListener("click", async () => {
    try {
      let rows = tables[validationTableIdx]?.records || [];

      const status = statusFilter.value;
      const channel = channelFilter.value;
      const severity = severityFilter.value;
      const confidenceMin = parseInt(confidenceMinInput.value) || 0;

      rows = rows.filter(r => {
        if (status && r.検証ステータス !== status) return false;
        if (channel && r.チャネルコード !== channel) return false;
        if (severity && r.重要度 !== severity) return false;
        if (r.総合スコア && r.総合スコア < confidenceMin) return false;
        return true;
      });

      renderValidationRows(rows);
    } catch (e) {
      console.error("検索エラー:", e);
    }
  });

  // 6. CSVエクスポート
  exportBtn.addEventListener("click", () => {
    try {
      const rows = tables[validationTableIdx]?.records || [];
      const headers = ["受注ID", "チャネル", "検証ステータス", "エラーコード", "エラーメッセージ", "検証項目", "重要度", "信頼度スコア", "対応状況"];
      const csvContent = [
        "\uFEFF" + headers.join(","),
        ...rows.map(r => [
          (r.受注データID || r.id || "").substring(0, 12),
          r.チャネルコード || r.チャネル || "",
          r.検証ステータス || "",
          r.エラーコード || "",
          `"${(r.エラーメッセージ || "").replace(/"/g, '""')}"`,
          r.検証項目 || "",
          r.重要度 || "",
          r.総合スコア || r.信頼度 || "",
          r.対応状況 || ""
        ].join(","))
      ].join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `validation_results_${new Date().toISOString().split("T")[0]}.csv`;
      link.click();
    } catch (e) {
      console.error("エクスポートエラー:", e);
    }
  });

  // 7. 行クリックで詳細表示
  container.addEventListener("click", (e) => {
    const row = e.target.closest("tbody#validation-tbody tr");
    if (row && row.dataset.id) {
      const rows = tables[validationTableIdx]?.records || [];
      const selected = rows.find(r => (r.検証結果ID || r.id) === row.dataset.id);
      if (selected) {
        showDetail(selected);
      }
    }
  });

  // 初期化実行
  loadData();
}

