  // ========== 2. 詳細パネル表示 ==========
  function showDetailPanel() {
    if (!selectedScoreData) return;

    const detailPanel = container.querySelector("#detail-panel");
    const noSelection = container.querySelector("#no-selection");
    const correctionForm = container.querySelector("#correction-form");
    const noForm = container.querySelector("#no-form");

    detailPanel.style.display = "block";
    noSelection.style.display = "none";
    correctionForm.style.display = "block";
    noForm.style.display = "none";

    // 詳細情報を埋める
    container.querySelector("#detail-order-id").textContent = selectedScoreData.受注データID || "—";
    container.querySelector("#detail-total-score").textContent = selectedScoreData.総合スコア || 0;
    container.querySelector("#detail-warning-level").textContent = selectedScoreData.警告レベル || "—";
    container.querySelector("#detail-completeness").textContent = selectedScoreData.完全性スコア || 0;
    container.querySelector("#detail-accuracy").textContent = selectedScoreData.正確性スコア || 0;
    container.querySelector("#detail-consistency").textContent = selectedScoreData.一貫性スコア || 0;

    // OCR結果を取得して表示
    const ocrResult = tables[ocrTableIdx]?.records?.find(r => r.order_id === selectedScoreData.受注データID);
    container.querySelector("#detail-ocr-result").textContent = ocrResult?.raw_ocr_text || "OCR結果なし";

    // 修正対象フラグ
    container.querySelector("#detail-needs-correction").checked = selectedScoreData.警告フラグ || false;

    // 修正前値を表示
    container.querySelector("#correction-before").textContent = selectedScoreData.検証値 || "—";
    container.querySelector("#correction-after").value = "";
    container.querySelector("#correction-reason").value = "";
    container.querySelector("#correction-comment").value = "";

    // スコアゲージを描画
    drawScoreGauge(selectedScoreData.総合スコア || 0);
  }

  // ========== 3. スコアゲージ描画（Canvas） ==========
  function drawScoreGauge(score) {
    const canvas = container.querySelector("#score-gauge");
    const ctx = canvas.getContext("2d");
    const w = canvas.offsetWidth;
    const h = canvas.offsetHeight;

    ctx.clearRect(0, 0, w, h);

    // 背景（グレー）
    ctx.fillStyle = "rgba(100,100,100,0.3)";
    ctx.fillRect(0, 0, w, h);

    // スコアバー（色は信頼度に応じて変更）
    const ratio = Math.max(0, Math.min(1, score / 100));
    const barColor = score >= 70 ? "#64c864" : score >= 40 ? "#ffa500" : "#ff6464";
    ctx.fillStyle = barColor;
    ctx.fillRect(0, 0, w * ratio, h);

    // テキスト
    ctx.fillStyle = "#ffffff";
    ctx.font = "bold 12px sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(`${score}%`, w / 2, h / 2);
  }

  // ========== 4. 検索・フィルタ処理 ==========
  function applyFilters() {
    const orderId = container.querySelector("#input-order-id").value.toLowerCase();
    const scoreRange = container.querySelector("#select-score-range").value;
    const warningLevel = container.querySelector("#select-warning-level").value;
    const sortBy = container.querySelector("#select-sort").value;

    let filtered = allScores.filter(s => {
      if (orderId && !s.受注データID?.toLowerCase().includes(orderId)) return false;
      if (scoreRange === "0-30" && s.総合スコア > 30) return false;
      if (scoreRange === "31-60" && (s.総合スコア <= 30 || s.総合スコア > 60)) return false;
      if (scoreRange === "61-100" && s.総合スコア <= 60) return false;
      if (warningLevel && s.警告レベル !== warningLevel) return false;
      return true;
    });

    // ソート
    if (sortBy === "score-asc") {
      filtered.sort((a, b) => (a.総合スコア || 0) - (b.総合スコア || 0));
    } else if (sortBy === "score-desc") {
      filtered.sort((a, b) => (b.総合スコア || 0) - (a.総合スコア || 0));
    } else if (sortBy === "priority") {
      const priorityMap = { "高": 1, "中": 2, "低": 3 };
      filtered.sort((a, b) => (priorityMap[a.警告レベル] || 99) - (priorityMap[b.警告レベル] || 99));
    } else if (sortBy === "date-new") {
      filtered.sort((a, b) => new Date(b.更新日時 || 0) - new Date(a.更新日時 || 0));
    }

    renderScoreList(filtered);
  }

  // ========== 5. 初期データ読み込み ==========
  async function initData() {
    const scores = tables[scoreTableIdx]?.records || [];
    allScores = scores;
    renderScoreList(allScores);
  }

  // ========== 6. イベントリスナー登録 ==========

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", applyFilters);

  // リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#input-order-id").value = "";
    container.querySelector("#select-score-range").value = "";
    container.querySelector("#select-warning-level").value = "";
    container.querySelector("#select-sort").value = "score-asc";
    applyFilters();
  });

  // 修正を保存ボタン
  container.querySelector("#btn-save-correction").addEventListener("click", async () => {
    const correctionAfter = container.querySelector("#correction-after").value.trim();
    const reason = container.querySelector("#correction-reason").value;
    const comment = container.querySelector("#correction-comment").value.trim();

    if (!correctionAfter) {
      alert("修正後の値を入力してください");
      return;
    }
    if (!reason) {
      alert("修正理由を選択してください");
      return;
    }

    // 修正履歴を保存
    const correctionData = {
      受注データID: selectedScoreData.受注データID,
      修正項目名: selectedScoreData.検証項目 || "不明",
      修正前値: selectedScoreData.検証値 || "",
      修正後値: correctionAfter,
      修正理由: reason,
      修正備考: comment,
      修正ユーザーID: "current-user-id",
      修正日時: new Date().toISOString(),
      検証結果ID: selectedScoreData.信頼度スコアID
    };

    const saved = await window.aivicApi.save(correctionTableIdx, correctionData);
    if (saved) {
      alert("修正を保存しました");
      container.querySelector("#correction-after").value = "";
      container.querySelector("#correction-reason").value = "";
      container.querySelector("#correction-comment").value = "";
      // 再度フィルタを適用して一覧を更新
      applyFilters();
    }
  });

  // キャンセルボタン
  container.querySelector("#btn-cancel-correction").addEventListener("click", () => {
    container.querySelector("#correction-after").value = "";
    container.querySelector("#correction-reason").value = "";
    container.querySelector("#correction-comment").value = "";
  });

  // 初期化実行
  initData();
}
